INSERT INTO punchlines (id, created_by, updated_by, inserted_at, updated_at, line) VALUES
    ('punchlines-12345678901234567890119', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', '2026-08-03 12:17:22', '2026-08-03 12:17:22', 'A voice broke through the thunder and the rain as the paint ran down the church walls, saying, "Repaint! And thin no more!"'),
    ('punchlines-12345678901234567890120', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', '2026-08-03 12:17:22', '2026-08-03 12:17:22', 'The second string said to the bartender, "You''ll have to excuse my buddy here … he''s not NULL Terminated."'),
    ('punchlines-12345678901234567890121', 'users-EvZyNFjBRmZhupSTTWBGRvx', 'users-EvZyNFjBRmZhupSTTWBGRvx', '2026-08-03 12:17:22', '2026-08-03 12:17:22', 'The bar tender exclaimed. "Hey! Aren''t you that string I told to get lost?" The string said to the bar tender, "No sir! I''m a frayed knot!"'),
    ('punchlines-12345678901234567890122', 'users-EvZyNFjBRmZhupSTTWBGRvm', 'users-EvZyNFjBRmZhupSTTWBGRvm', '2025-10-01 12:17:22', '2025-10-01 12:17:22', '"Oh yes he does," the first kid says to the other. "I''ve seen the cigarette stains on his underwear."'),
    ('punchlines-12345678901234567890123', 'users-EvZyNFjBRmZhupSTTWBGRvm', 'users-EvZyNFjBRmZhupSTTWBGRvm', '2025-10-01 12:17:22', '2025-10-01 12:17:22', 'She looked surprised.'),
    ('punchlines-12345678901234567890124', 'users-EvZyNFjBRmZhupSTTWBGRvm', 'users-EvZyNFjBRmZhupSTTWBGRvm', '2025-05-01 12:17:22', '2025-05-01 12:17:22', 'I now live in constant fear.'),
    ('punchlines-12345678901234567890125', 'users-EvZyNFjBRmZhupSTTWBGRvg', 'users-EvZyNFjBRmZhupSTTWBGRvg', '2024-04-01 12:17:22', '2024-04-01 12:17:22', 'Because they make up everything.'),
    ('punchlines-12345678901234567890126', 'users-EvZyNFjBRmZhupSTTWBGRvg', 'users-EvZyNFjBRmZhupSTTWBGRvg', '2024-03-01 12:17:22', '2024-03-01 12:17:22', 'My computer said "No problem, I''ll go to sleep."'),
    ('punchlines-12345678901234567890127', 'users-EvZyNFjBRmZhupSTTWBGRvg', 'users-EvZyNFjBRmZhupSTTWBGRvg', '2023-02-01 12:17:22', '2023-02-01 12:17:22', 'She whispered, "They''re right behind you."')
